import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'

async function getDashboardData() {
  const res = await fetch('https://api.example.com/dashboard')
  return res.json()
}

export default async function Page() {
  const data = await getDashboardData()

  return (
    <main>
      <h1>Dashboard</h1>
      <CardStats
        totalRevenue={data.totalRevenue}
        totalInvoices={data.totalInvoices}
      />
      <RevenueChart revenue={data.revenue} />
      <LatestInvoices invoices={data.invoices} />
    </main>
  )
}

import { cacheLife } from 'next/cache'

interface RevenueItem {
  month: string
  amount: number
}

async function getRevenueData(): Promise<RevenueItem[]> {
  'use cache'
  cacheLife('minutes')

  // Simulate API delay
  await new Promise((resolve) => setTimeout(resolve, 1000))

  // Mock data - in production this would be a real API call
  return [
    { month: 'Jan', amount: 4000 },
    { month: 'Feb', amount: 3000 },
    { month: 'Mar', amount: 5000 },
    { month: 'Apr', amount: 4500 },
    { month: 'May', amount: 6000 },
    { month: 'Jun', amount: 5500 },
  ]
}

export async function RevenueChart() {
  const revenue = await getRevenueData()

  return (
    <div className="chart">
      <h2>Revenue</h2>
      <ul>
        {revenue.map((item) => (
          <li key={item.month}>
            {item.month}: ${item.amount.toLocaleString()}
          </li>
        ))}
      </ul>
    </div>
  )
}

export function RevenueChartSkeleton() {
  return (
    <div className="chart skeleton">
      <h2>Revenue</h2>
      <div className="skeleton-list">
        {[...Array(6)].map((_, i) => (
          <div key={i} className="skeleton-row">
            <span className="skeleton-text" style={{ width: '40px' }} />
            <span className="skeleton-text" style={{ width: '80px' }} />
          </div>
        ))}
      </div>
    </div>
  )
}

import { cacheLife } from 'next/cache'

interface Invoice {
  id: string
  name: string
  amount: number
}

async function getInvoicesData(): Promise<Invoice[]> {
  'use cache'
  cacheLife('minutes')

  // Simulate API delay
  await new Promise((resolve) => setTimeout(resolve, 800))

  // Mock data - in production this would be a real API call
  return [
    { id: '1', name: 'Acme Corp', amount: 1200 },
    { id: '2', name: 'TechStart Inc', amount: 850 },
    { id: '3', name: 'Global Solutions', amount: 2100 },
    { id: '4', name: 'Digital Dynamics', amount: 1750 },
    { id: '5', name: 'Future Systems', amount: 950 },
  ]
}

export async function LatestInvoices() {
  const invoices = await getInvoicesData()

  return (
    <div className="invoices">
      <h2>Latest Invoices</h2>
      <ul>
        {invoices.map((invoice) => (
          <li key={invoice.id}>
            {invoice.name} - ${invoice.amount.toLocaleString()}
          </li>
        ))}
      </ul>
    </div>
  )
}

export function LatestInvoicesSkeleton() {
  return (
    <div className="invoices skeleton">
      <h2>Latest Invoices</h2>
      <div className="skeleton-list">
        {[...Array(5)].map((_, i) => (
          <div key={i} className="skeleton-row">
            <span className="skeleton-text" style={{ width: '120px' }} />
            <span className="skeleton-text" style={{ width: '60px' }} />
          </div>
        ))}
      </div>
    </div>
  )
}

import { cacheLife } from 'next/cache'

interface StatsData {
  totalRevenue: number
  totalInvoices: number
}

async function getStatsData(): Promise<StatsData> {
  'use cache'
  cacheLife('minutes')

  // Simulate API delay
  await new Promise((resolve) => setTimeout(resolve, 600))

  // Mock data - in production this would be a real API call
  return {
    totalRevenue: 125000,
    totalInvoices: 42,
  }
}

export async function CardStats() {
  const { totalRevenue, totalInvoices } = await getStatsData()

  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card">
        <h2>Total Revenue</h2>
        <p>${totalRevenue.toLocaleString()}</p>
      </div>
      <div className="card">
        <h2>Total Invoices</h2>
        <p>{totalInvoices}</p>
      </div>
    </div>
  )
}

export function CardStatsSkeleton() {
  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card skeleton">
        <h2>Total Revenue</h2>
        <div className="skeleton-text large" />
      </div>
      <div className="card skeleton">
        <h2>Total Invoices</h2>
        <div className="skeleton-text large" />
      </div>
    </div>
  )
}

// Page-level loading is no longer needed since we have granular Suspense boundaries
// with individual skeleton components for each section
export default function Loading() {
  return null
}

